// Step 1: Validate payload and calculate SHA-256 content hash
const crypto = require('crypto');

const item = $input.first().json;
const body = item.body || item;

if (!body.fileName || !body.fileName.trim()) {
  throw new Error('fileName is required in ingestion payload');
}

const fileName = body.fileName.trim();
const source = body.source || 'n8n-automated-sync';
const fileUrl = body.fileUrl || body.source || '';
const rawContent = body.content || fileUrl || fileName;

// Compute deterministic SHA-256 hash
const hash = 'sha256:' + crypto.createHash('sha256').update(rawContent, 'utf8').digest('hex');

const fileType = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : 'txt';
const mimeType = body.mimeType || (fileType === 'pdf' ? 'application/pdf' : 'text/plain');

return [{
  json: {
    documentId: body.documentId || crypto.randomUUID(),
    fileName: fileName,
    fileType: fileType,
    mimeType: mimeType,
    source: source,
    fileUrl: fileUrl,
    fileSize: body.fileSize || Buffer.byteLength(rawContent, 'utf8'),
    contentHash: hash,
    ownerId: body.ownerId || null,
    attempt: 1
  }
}];

